using H2Sharp.Api;

namespace H2Sharp.Message;

internal static class ErrorCodeKind
{
    /// <summary>
    /// The default bucket, matching the JdbcSQLException that H2 falls back to.
    /// </summary>
    private const SqlExceptionKind Default = SqlExceptionKind.Unspecified;

    /// <summary>
    /// Maps an H2 error code to the exception bucket H2 would have used.
    /// </summary>
    /// <param name="errorCode">the H2 error code</param>
    /// <returns>the exception bucket</returns>
    internal static SqlExceptionKind GetKind(int errorCode)
    {
        // Use SQLState class value to detect type
        switch (errorCode / 1_000)
        {
            case 2:
                return SqlExceptionKind.NonTransient;

            case 7:
            case 21:
            case 42:
            case 54:
                return SqlExceptionKind.SyntaxError;

            case 8:
                return SqlExceptionKind.NonTransientConnection;

            case 22:
                return SqlExceptionKind.Data;

            case 23:
                return SqlExceptionKind.IntegrityConstraintViolation;

            case 28:
                return SqlExceptionKind.InvalidAuthorizationSpec;

            case 40:
                return SqlExceptionKind.TransactionRollback;

        }

        // Check error code
        switch (errorCode)
        {
            case ErrorCode.GeneralError1:
            case ErrorCode.UnknownDataType1:
            case ErrorCode.MethodNotAllowedForQuery:
            case ErrorCode.MethodOnlyAllowedForQuery:
            case ErrorCode.SequenceExhausted:
            case ErrorCode.ObjectClosed:
            case ErrorCode.CannotDropCurrentUser:
            case ErrorCode.UnsupportedSettingCombination:
            case ErrorCode.FileRenameFailed2:
            case ErrorCode.FileDeleteFailed1:
            case ErrorCode.IoException1:
            case ErrorCode.NotOnUpdatableRow:
            case ErrorCode.IoException2:
            case ErrorCode.TraceFileError2:
            case ErrorCode.AdminRightsRequired:
            case ErrorCode.ErrorExecutingTrigger3:
            case ErrorCode.CommitRollbackNotAllowed:
            case ErrorCode.FileCreationFailed1:
            case ErrorCode.SavepointIsInvalid1:
            case ErrorCode.SavepointIsUnnamed:
            case ErrorCode.SavepointIsNamed:
            case ErrorCode.NotEnoughRightsFor1:
            case ErrorCode.DatabaseIsReadOnly:
            case ErrorCode.WrongXidFormat1:
            case ErrorCode.UnsupportedCompressionOptions1:
            case ErrorCode.UnsupportedCompressionAlgorithm1:
            case ErrorCode.CompressionError:
            case ErrorCode.ExceptionInFunction1:
            case ErrorCode.ErrorAccessingLinkedTable2:
            case ErrorCode.FileNotFound1:
            case ErrorCode.InvalidClass2:
            case ErrorCode.DatabaseIsNotPersistent:
            case ErrorCode.ResultSetNotUpdatable:
            case ErrorCode.ResultSetNotScrollable:
            case ErrorCode.MethodNotAllowedForPreparedStatement:
            case ErrorCode.AccessDeniedToClass1:
            case ErrorCode.ResultSetReadonly:
            case ErrorCode.CurrentSequenceValueIsNotDefinedInSession1:
                return SqlExceptionKind.NonTransient;

            case ErrorCode.FeatureNotSupported1:
                return SqlExceptionKind.FeatureNotSupported;

            case ErrorCode.LockTimeout1:
            case ErrorCode.StatementWasCanceled:
            case ErrorCode.LobClosedOnTimeout1:
                return SqlExceptionKind.Timeout;

            case ErrorCode.FunctionMustReturnResultSet1:
            case ErrorCode.InvalidTriggerFlags1:
            case ErrorCode.SumOrAvgOnWrongDatatype1:
            case ErrorCode.MustGroupByColumn1:
            case ErrorCode.SecondPrimaryKey:
            case ErrorCode.FunctionNotFound1:
            case ErrorCode.ColumnMustNotBeNullable1:
            case ErrorCode.UserNotFound1:
            case ErrorCode.UserAlreadyExists1:
            case ErrorCode.SequenceAlreadyExists1:
            case ErrorCode.SequenceNotFound1:
            case ErrorCode.ViewNotFound1:
            case ErrorCode.ViewAlreadyExists1:
            case ErrorCode.TriggerAlreadyExists1:
            case ErrorCode.TriggerNotFound1:
            case ErrorCode.ErrorCreatingTriggerObject3:
            case ErrorCode.ConstraintAlreadyExists1:
            case ErrorCode.SubqueryIsNotSingleColumn:
            case ErrorCode.InvalidUseOfAggregateFunction1:
            case ErrorCode.ConstraintNotFound1:
            case ErrorCode.AmbiguousColumnName1:
            case ErrorCode.OrderByNotInResult:
            case ErrorCode.RoleAlreadyExists1:
            case ErrorCode.RoleNotFound1:
            case ErrorCode.UserOrRoleNotFound1:
            case ErrorCode.RolesAndRightCannotBeMixed:
            case ErrorCode.MethodsMustHaveDifferentParameterCounts2:
            case ErrorCode.RoleAlreadyGranted1:
            case ErrorCode.ColumnIsPartOfIndex1:
            case ErrorCode.FunctionAliasAlreadyExists1:
            case ErrorCode.FunctionAliasNotFound1:
            case ErrorCode.SchemaAlreadyExists1:
            case ErrorCode.SchemaNotFound1:
            case ErrorCode.SchemaNameMustMatch:
            case ErrorCode.ColumnContainsNullValues1:
            case ErrorCode.SequenceBelongsToATable1:
            case ErrorCode.ColumnIsReferenced1:
            case ErrorCode.CannotDropLastColumn:
            case ErrorCode.IndexBelongsToConstraint2:
            case ErrorCode.ClassNotFound1:
            case ErrorCode.MethodNotFound1:
            case ErrorCode.CollationChangeWithDataTable1:
            case ErrorCode.SchemaCanNotBeDropped1:
            case ErrorCode.RoleCanNotBeDropped1:
            case ErrorCode.CannotTruncate1:
            case ErrorCode.CannotDrop2:
            case ErrorCode.ViewIsInvalid2:
            case ErrorCode.TypesAreNotComparable2:
            case ErrorCode.ConstantAlreadyExists1:
            case ErrorCode.ConstantNotFound1:
            case ErrorCode.LiteralsAreNotAllowed:
            case ErrorCode.CannotDropTable1:
            case ErrorCode.DomainAlreadyExists1:
            case ErrorCode.DomainNotFound1:
            case ErrorCode.WithTiesWithoutOrderBy:
            case ErrorCode.CannotMixIndexedAndUnindexedParams:
            case ErrorCode.TransactionNotFound1:
            case ErrorCode.AggregateNotFound1:
            case ErrorCode.WindowNotFound1:
            case ErrorCode.CanOnlyAssignToVariable1:
            case ErrorCode.PublicStaticJavaMethodNotFound1:
            case ErrorCode.JavaObjectSerializerChangeWithDataTable:
            case ErrorCode.ForUpdateIsNotAllowedInDistinctOrGroupedSelect:
            case ErrorCode.InvalidValuePrecision:
            case ErrorCode.InvalidValueScale:
            case ErrorCode.ConstraintIsUsedByConstraint2:
            case ErrorCode.UncomparableReferencedColumn2:
            case ErrorCode.GeneratedColumnCannotBeAssigned1:
            case ErrorCode.GeneratedColumnCannotBeUpdatableByConstraint2:
            case ErrorCode.ColumnAliasIsNotSpecified1:
            case ErrorCode.GroupByNotInTheResult:
                return SqlExceptionKind.SyntaxError;

            case ErrorCode.HexStringOdd1:
            case ErrorCode.HexStringWrong1:
            case ErrorCode.InvalidValue2:
            case ErrorCode.SequenceAttributesInvalid7:
            case ErrorCode.InvalidToCharFormat:
            case ErrorCode.ParameterNotSet1:
            case ErrorCode.ParseError1:
            case ErrorCode.InvalidToDateFormat:
            case ErrorCode.StringFormatError1:
            case ErrorCode.SerializationFailed1:
            case ErrorCode.DeserializationFailed1:
            case ErrorCode.ScalarSubqueryContainsMoreThanOneRow:
            case ErrorCode.StepSizeMustNotBeZero:
                return SqlExceptionKind.Data;

            case ErrorCode.UrlRelativeToCwd:
            case ErrorCode.DatabaseNotFound1:
            case ErrorCode.DatabaseNotFoundWithIfExists1:
            case ErrorCode.RemoteDatabaseNotFound1:
            case ErrorCode.TraceConnectionNotClosed:
            case ErrorCode.DatabaseAlreadyOpen1:
            case ErrorCode.FileCorrupted1:
            case ErrorCode.UrlFormatError2:
            case ErrorCode.DriverVersionError2:
            case ErrorCode.FileVersionError1:
            case ErrorCode.FileEncryptionError1:
            case ErrorCode.WrongPasswordFormat:
            case ErrorCode.UnsupportedCipher:
            case ErrorCode.UnsupportedLockMethod1:
            case ErrorCode.ExceptionOpeningPort2:
            case ErrorCode.DuplicateProperty1:
            case ErrorCode.ConnectionBroken1:
            case ErrorCode.UnknownMode1:
            case ErrorCode.ClusterErrorDatabaseRunsAlone:
            case ErrorCode.ClusterErrorDatabaseRunsClustered1:
            case ErrorCode.DatabaseIsClosed:
            case ErrorCode.ErrorSettingDatabaseEventListener2:
            case ErrorCode.OutOfMemory:
            case ErrorCode.UnsupportedSetting1:
            case ErrorCode.RemoteConnectionNotAllowed:
            case ErrorCode.DatabaseCalledAtShutdown:
            case ErrorCode.CannotChangeSettingWhenOpen1:
            case ErrorCode.DatabaseIsInExclusiveMode:
            case ErrorCode.InvalidDatabaseName1:
            case ErrorCode.AuthenticatorNotAvailable:
            case ErrorCode.MethodDisabledOnAutocommitTrue:
                return SqlExceptionKind.NonTransientConnection;

            case ErrorCode.RowNotFoundWhenDeleting1:
            case ErrorCode.ConcurrentUpdate1:
            case ErrorCode.RowNotFoundInPrimaryIndex:
                return SqlExceptionKind.Transient;
        }

        // Default
        return Default;
    }
}
